import spidev
import time
import signal
import sys

class LoadCellReader:
    def __init__(self):
        self.spi = None
        self.open_spi()

    def open_spi(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)  # Open SPI device at /dev/spidev0.0
            self.spi.max_speed_hz = 50000
            self.spi.mode = 0b00
            self.spi.bits_per_word = 8
        except OSError as e:
            print(f"Error opening SPI device: {e}")
            sys.exit(1)

    def send_spi_command(self, spi, data):
        try:
            response = spi.xfer2([0x01, 0x80, 0x00] + data)
            return response
        except OSError as e:
            print(f"Error sending SPI command: {e}")
            return None

    def extract_10bit(self, response):
        if response is None or len(response) < 3:
            return None
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        response = self.send_spi_command(self.spi, [0x00])
        if response is None:
            return None
        return self.extract_10bit(response)

    def convert_to_weight(self, raw_data):
        if raw_data is None:
            return None
        return float(raw_data) * (5.0 / 1023.0)

    def close(self):
        if self.spi:
            self.spi.close()
            print("SPI device closed.")

def main():
    reader = LoadCellReader()
    try:
        while True:
            raw_data = reader.read_raw_data()
            weight = reader.convert_to_weight(raw_data)
            if weight is not None:
                print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        reader.close()

def signal_handler(sig, frame):
    print("Received SIGTERM, shutting down...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGTERM, signal_handler)
    main()

