try:
    bus = smbus2.SMBus(1)
except smbus2.SMBusError as e:
    print(f"Failed to initialize I2C bus: {e}")
    exit(1)

# Initialize ADS1115 ADC
try:
    adc = ADS1115(bus, address=0x48)
except OSError as e:
    print(f"Failed to initialize ADS1115: {e}")
    exit(1)

# Initialize camera
try:
    camera = Picamera2()
    camera.start()
except Exception as e:
    print(f"Failed to start camera: {e}")
    exit(1)

# Initialize MQTT client
client = mqtt.Client()
client.connect("mqtt.example.com", 1883, 60)

# Define button to trigger camera capture
button = Button(17)

# Function to read ADC values
def read_adc():
    try:
        values = []
        for channel in range(4):
            ain = AnalogIn(adc, channel)
            while True:
                if ain.value is not None:
                    values.append(ain.value)
                    break
                time.sleep(0.01)
        return values
    except Exception as e:
        print(f"Error reading ADC channel {channel}: {e}")
        return None

# Function to capture image and publish to MQTT
def capture_and_publish():
    try:
        camera.capture_file("image.jpg")
        with open("image.jpg", "rb") as f:
            image_data = f.read()
        client.publish("camera/image", image_data)
    except Exception as e:
        print(f"Error capturing and publishing image: {e}")

# Main loop
