    while True:
        if button.is_pressed:
            capture_and_publish()
        values = read_adc()
        if values is not None:
            print(f"ADC values: {values}")
        time.sleep(0.05)
except KeyboardInterrupt:
    pass

# Clean up
try:
    camera.stop()
    client.disconnect()
    bus.close()
except Exception as e:
    print(f"Error cleaning up: {e}")

import RPi.GPIO as GPIO
