import time
import queue
import logging
import argparse

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.gpio = None
        self.running = False

        if sensor_type == 'digital':
            if not gpio_pins:
                raise ValueError("GPIO pins must be provided for digital sensors.")
            self.gpio = GPIO
            self.gpio.setmode(GPIO.BCM)
            for pin in gpio_pins:
                self.gpio.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        elif sensor_type == 'analog':
            if not channels:
                raise ValueError("Channels must be provided for analog sensors.")
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = spi_speed
        else:
            raise ValueError("Invalid sensor type. Supported types are 'digital' and 'analog'.")

    def read_sensor(self):
        if self.sensor_type == 'digital':
            for pin in self.gpio_pins:
                if self.gpio.input(pin) == 1:
                    return True
        elif self.sensor_type == 'analog':
            adc_value = self.read_analog()
            if adc_value >= self.threshold:
                return True
        return False

    def read_analog(self):
        adc_value = 0
        for channel in self.channels:
            adc_value = (adc_value << 8) + self.spi.xfer2([1, (8 + channel) << 4, 0])[1]
        return adc_value

    def run(self):
        self.running = True
        while self.running:
            if self.read_sensor():
                if self.log_queue:
                    self.log_queue.put((self.sensor_id, time.time()))
                time.sleep(0.1)
            time.sleep(1 / self.sample_rate)

    def stop(self):
        self.running = False
        if self.sensor_type == 'analog':
            self.spi.close()
        if self.gpio:
            GPIO.cleanup()

def main():
    parser = argparse.ArgumentParser(description="Sound sensor monitoring")
    parser.add_argument('--sensor_type', choices=['digital', 'analog'], required=True)
    parser.add_argument('--threshold', type=int, required=True)
    parser.add_argument('--sample_rate', type=int, required=True)
    parser.add_argument('--log_file', required=True)
    parser.add_argument('--gpio_pins', nargs='+', type=int, help='GPIO pins for digital sensors')
    parser.add_argument('--channels', nargs='+', type=int, help='Channels for analog sensors')
    parser.add_argument('--spi_speed', type=int, default=1000000, help='SPI speed in Hz')

    args = parser.parse_args()

    log_queue = queue.Queue()
    logging.basicConfig(filename=args.log_file, level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

    sensors = []
    for sensor_id in range(1, args.sensor_type == 'digital' and len(args.gpio_pins) + 1 or len(args.channels) + 1):
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
        sensors.append(sensor)
        sensor_thread = threading.Thread(target=sensor.run)
        sensor_thread.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()

if __name__ == "__main__":
    import threading
    main()

