            time.sleep(5)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        light_sensor.close()
        temp_sensor.close()
        logging.info("GPIO devices closed.")

if __name__ == '__main__':
    main()

