import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    def __init__(self):
        try:
            self.bus = smbus2.SMBus(1)
            self.address = 0x38
            self.status_register = 0x71
            self.command_register = 0xAC
            self.data_register = 0x71
            self.crc_polynomial = 0x31
            self.crc_initial_value = 0xFF
            self.crc_table = self._generate_crc_table()
            self._verify_sensor()
        except Exception as e:
            logging.error(f"Failed to initialize DHT20 sensor: {e}")
            self.bus = None

    def _verify_sensor(self):
        try:
            status = self.bus.read_byte_data(self.address, self.status_register)
            if status & 0x80:
                logging.error("DHT20 sensor is not present or not responding.")
                self.bus = None
        except Exception as e:
            logging.error(f"Failed to verify DHT20 sensor: {e}")
            self.bus = None

    def _generate_crc_table(self):
        crc_table = [0] * 256
        for i in range(256):
            crc = i
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ self.crc_polynomial
                else:
                    crc <<= 1
            crc_table[i] = crc
        return crc_table

    def _calculate_crc(self, data):
        crc = self.crc_initial_value
        for byte in data:
            crc = (crc << 8) ^ self.crc_table[(crc >> 8) ^ byte]
        return crc

    def measure(self):
        try:
            self.bus.write_byte_data(self.address, self.command_register, 0x00)
            start_time = time.time()
            while time.time() - start_time < 0.1:
                status = self.bus.read_byte_data(self.address, self.status_register)
                if not (status & 0x80):
                    break
                time.sleep(0.01)
            if time.time() - start_time >= 0.1:
                logging.error("Measurement timed out.")
                return None, None, True

            data = self.bus.read_i2c_block_data(self.address, self.data_register, 7)
            crc = self._calculate_crc(data[:6])
            if crc != data[6]:
                logging.error("CRC error in measurement data.")
                return None, None, True

            humidity_raw = (data[1] << 16) | (data[2] << 8) | data[3]
            temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5]

            temperature = float(temperature_raw) / 5242.88 - 50.0
            humidity = float(humidity_raw) / 0x100000 * 100.0

            return temperature, humidity, False
        except Exception as e:
            logging.error(f"Failed to measure DHT20 sensor: {e}")
            return None, None, True

    def __del__(self):
        if self.bus:
            self.bus.close()

if __name__ == "__main__":
    dht20 = DHT20()
    if dht20.bus:
        temperature, humidity, crc_error = dht20.measure()
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
        else:
            print("Failed to measure DHT20 sensor.")
    else:
        print("DHT20 sensor not initialized.")

def signal_handler(sig, frame):
    logging.info("Received signal, cleaning up and exiting.")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
