class DHT20Sensor:
    def __init__(self, i2c_bus=1, i2c_address=0x38):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.i2c = None
        self.dht20 = None
        self.last_reading = None
        self.last_read_time = 0

    def begin(self):
        try:
            self.i2c = smbus2.SMBus(self.i2c_bus)
            time.sleep(0.5)  # Wait for sensor to stabilize
            status = self.i2c.read_byte_data(self.i2c_address, 0x71)
            if (status & 0x18) != 0x18:
                logging.error("Failed to initialize DHT20 sensor: status register 0x71 is not 0x18")
                return False
            self.dht20 = DHT20(self.i2c, self.i2c_address)
            return True
        except OSError as e:
            logging.warning(f"Failed to open I2C bus: {e}")
            return False

    def get_temperature_and_humidity(self):
        if time.time() - self.last_read_time < 2:
            return self.last_reading

        if not self.begin():
            logging.error("Failed to initialize DHT20 sensor")
            return None, None, True

