import subprocess
import time
from gpiozero import PWMOutputDevice
import signal
import sys

# Initialize PWM fan
try:
    fan = PWMOutputDevice(14, frequency=100)
except Exception as e:
    print(f"Failed to initialize PWM fan: {e}")
    fan = None
    print("Running in degraded mode without PWM fan control.")

# Function to read CPU temperature
def read_cpu_temperature():
    try:
        result = subprocess.run(['vcgencmd', 'measure_temp'], capture_output=True, text=True, check=True)
        temp_str = result.stdout.strip().split('=')[1]
        temp_celsius = float(temp_str[:-2])
        return temp_celsius
    except subprocess.CalledProcessError as e:
        print(f"Error reading CPU temperature: {e}")
        return None

# Function to set fan duty cycle based on temperature
def set_fan_duty_cycle(temp_celsius):
    if temp_celsius is None:
        return
    if temp_celsius > 70:
        duty_cycle = 100
    elif temp_celsius > 60:
        duty_cycle = 85
    elif temp_celsius > 50:
        duty_cycle = 70
    elif temp_celsius > 40:
        duty_cycle = 50
    elif temp_celsius > 32:
        duty_cycle = 25
    elif temp_celsius > 25:
        duty_cycle = 15
    else:
        duty_cycle = 0
    if fan is not None:
        fan.value = duty_cycle / 100.0
    print(f"Setting fan duty cycle to {duty_cycle}%")

# Signal handler for SIGINT and SIGTERM
def signal_handler(sig, frame):
    if fan is not None:
        fan.close()
    sys.exit(0)

