import logging
import time
import zmq
from gpiozero import PWMOutputDevice, OutputDevice
from gpiozero.pins.pigpio import PiGPIOFactory
from signal import signal, SIGINT, SIGTERM

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class PIDHandler:
    def __init__(self, pwm=True):
        self.factory = PiGPIOFactory()
        self.pwm_output = PWMOutputDevice(12, factory=self.factory) if pwm else OutputDevice(15, factory=self.factory)
        self.pwm_output.frequency = 1000
        self.pwm_output.duty_cycle = 0.0
        self.global_err_state = False
        self.last_msg = time.time()
        self.context = zmq.Context()
        self.socket = self.context.socket(zmq.SUB)
        self.socket.bind("tcp://*:5555")
        self.socket.setsockopt(zmq.SUBSCRIBE, b"")
        self.callbacks = {}

    def update_error_output(self):
        if self.pwm_output:
            self.pwm_output.duty_cycle = 1.0 if self.global_err_state else 0.0
        else:
            self.pwm_output.value = self.global_err_state

    def set_error_output(self, state: bool):
        self.global_err_state = state
        self.update_error_output()

    def handle_message(self):
        try:
            message = self.socket.recv(zmq.NOBLOCK)
            if message:
                self.last_msg = time.time()
                for callback in self.callbacks.values():
                    callback(message)
        except zmq.ZMQError as e:
            if e.errno != zmq.EAGAIN:
                logging.error(f"ZMQ error: {e}")

    def cleanup(self):
        self.socket.close()
        self.context.term()
        if self.pwm_output:
            self.pwm_output.close()

    def register_callback(self, topic: str, callback):
        if topic not in self.callbacks:
            self.callbacks[topic] = []
        self.callbacks[topic].append(callback)

    def unregister_callback(self, topic: str, callback):
        if topic in self.callbacks:
            self.callbacks[topic].remove(callback)
            if not self.callbacks[topic]:
                del self.callbacks[topic]

    def watchdog(self):
        while True:
            if time.time() - self.last_msg > 20:
                self.set_error_output(True)
            time.sleep(1)

    def signal_handler(self, signum, frame):
        self.cleanup()
        logging.info("Exiting...")
        exit(0)

if __name__ == "__main__":
    try:
        pid_handler = PIDHandler(pwm=True)
        pid_handler.register_callback("error", lambda message: logging.error(f"Received error message: {message}"))
        pid_handler.register_callback("data", lambda message: logging.info(f"Received data message: {message}"))
        pid_handler.watchdog_thread = threading.Thread(target=pid_handler.watchdog)
        pid_handler.watchdog_thread.start()
        signal(SIGINT, pid_handler.signal_handler)
        signal(SIGTERM, pid_handler.signal_handler)
        while True:
            pid_handler.handle_message()
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        pid_handler.cleanup()

