import pigpio
from gpiozero import OutputDevice
from typing import Union

class OutputPin:
    class InvalidPinError(Exception):
        """Custom exception for invalid pin number."""
        pass

    class InvalidValueError(Exception):
        """Custom exception for invalid initial value."""
        pass

    def __init__(self, pin_number: int, initial_value: int = 0):
        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pigpio = None
        self.output_device = None

        try:
            self.pigpio = pigpio.pi()
            if not self.pigpio.connected:
                raise pigpio.ConnectionFailedError("Failed to connect to pigpio daemon.")
            self.pigpio.set_mode(self.pin_number, pigpio.OUTPUT)
            self.output_device = OutputDevice(self.pin_number, initial_value=initial_value)
        except Exception as e:
            self.shutdown()
            raise e

    def set_value(self, value: int) -> None:
        if value not in (0, 1):
            raise self.InvalidValueError("Value must be 0 or 1.")
        try:
            self.output_device.value = value
        except Exception as e:
            self.shutdown()
            raise e

    def shutdown(self) -> None:
        if self.output_device:
            self.output_device.close()
        if self.pigpio:
            self.pigpio.stop()

if __name__ == '__main__':
    try:
        pin = OutputPin(17, initial_value=1)
        print("Toggling GPIO 17 every 0.5 seconds for 5 seconds...")
        for _ in range(10):
