# Stub implementations for spidev and gpiozero
class SpiDev:
    def __init__(self, bus=0, device=0):
        self.bus = bus
        self.device = device
        self.fd = None

    def open(self, bus, device):
        self.fd = open(f'/dev/spidev{bus}.{device}', 'wb')

    def close(self):
        if self.fd:
            self.fd.close()
            self.fd = None

    def xfer(self, data):
        if not self.fd:
            raise Exception("SPI device not open")
        self.fd.write(data)
        return self.fd.read(len(data))

class OutputDevice:
