        self.pin = pin
        self.active_high = active_high
        self.initial_value = initial_value
        self.value = initial_value

    def on(self):
        self.value = True

    def off(self):
        self.value = False

    def close(self):
        pass

# Stub implementations for Adafruit CircuitPython libraries
class AdafruitST7735:
    def __init__(self, spi, dc, rst, backlight):
        self.spi = spi
        self.dc = dc
        self.rst = rst
        self.backlight = backlight
        self.width = 128
        self.height = 128

    def init(self):
        pass

    def display(self, image):
        pass

    def set_orientation(self, orientation):
        pass

    def clear(self, color):
        pass

    def draw_text(self, text, x, y, font, color):
        pass

# Stub implementations for Paho MQTT v2
class MQTTClient:
    def __init__(self, client_id, server, port=1883):
        self.client_id = client_id
        self.server = server
        self.port = port
        self.connected = False

    def connect(self):
        self.connected = True

    def disconnect(self):
        self.connected = False

    def publish(self, topic, payload):
        pass

    def subscribe(self, topic):
        pass

    def loop_forever(self):
        pass

# Main program
class TFTDisplay:
    def __init__(self):
        self.spi = SpiDev()
        self.dc = gpiozero.OutputDevice(22)
        self.rst = gpiozero.OutputDevice(18)
        self.backlight = gpiozero.OutputDevice(23)
        self.st7735 = AdafruitST7735(self.spi, self.dc, self.rst, self.backlight)
        self.fonts = [ImageFont.truetype('DejaVuSans.ttf', i) for i in range(1, 9)]
        self.colors = [(255, 0, 0), (0, 255, 0), (0, 0, 255), (255, 255, 0), (255, 0, 255), (0, 255, 255)]
        self.texts = ['Quick', 'Brown', 'fox', 'jumped', 'over']
        self.fonts_extended = [ImageFont.truetype('DejaVuSans.ttf', 3), ImageFont.truetype('DejaVuSans.ttf', 4)]
        self.texts_extended = ['Quick', 'Brown', 'fox', 'jumped', 'over']

        try:
            self.spi.open(0, 0)
            self.spi.max_speed_hz = 32000000
            self.spi.mode = 0
            self.st7735.init()
            self.st7735.set_orientation(90)
            self.backlight.on()
            self.clear_screen()
            self.display_colors()
            self.display_text()
            self.display_extended_text()
            self.display_text_vertical()
            self.clear_screen()
            self.display_text('Fin.', font=self.fonts[7], color=self.colors[4])
        except Exception as e:
            print(f"An error occurred: {e}")
        finally:
            self.cleanup()

    def clear_screen(self):
        self.st7735.clear((0, 0, 0))

    def display_colors(self):
        for color in self.colors:
            self.st7735.clear(color)
            time.sleep(1)

    def display_text(self, text='', font=None, color=None):
        if not font:
            font = self.fonts[0]
        if not color:
            color = self.colors[0]
        image = Image.new('RGB', (self.st7735.width, self.st7735.height), (0, 0, 0))
        draw = ImageDraw.Draw(image)
        x, y = 0, 0
        for char in text:
            try:
                draw.text((x, y), char, font=font, fill=color)
                x += font.getsize(char)[0]
                if x >= self.st7735.width:
                    x = 0
                    y += font.getsize(char)[1]
            except Exception as e:
                print(f"Error displaying character '{char}': {e}")
        self.st7735.display(image)

    def display_extended_text(self):
        for font, text in zip(self.fonts_extended, self.texts_extended):
            try:
                self.display_text(text, font=font)
            except Exception as e:
                print(f"Error displaying extended text: {e}")

    def display_text_vertical(self):
        for i, text in enumerate(self.texts):
            self.display_text(text, font=self.fonts[i], color=self.colors[i])
            time.sleep(1)

    def cleanup(self):
        self.backlight.off()
        self.st7735.clear((0, 0, 0))
        self.st7735.close()
        self.spi.close()
        atexit.unregister(self.cleanup)

# Install SIGTERM handler
import signal
def signal_handler(sig, frame):
    print("SIGTERM received, cleaning up...")
    exit(0)
signal.signal(signal.SIGTERM, signal_handler)

# Run the program
if __name__ == "__main__":
    try:
        TFTDisplay()
    except KeyboardInterrupt:
        print("KeyboardInterrupt received, cleaning up...")
    except Exception as e:
        print(f"An error occurred: {e}")

