    fan = None

# Initialize Picamera2 for video capture
try:
    camera = Picamera2()
    camera.resolution = (640, 480)
    camera.framerate = 30
    camera.encoder = MJPEGEncoder()
    camera.output = FileOutput("output.mp4")
    camera.start()
except Exception as e:
    print(f"Failed to initialize camera: {e}")
    camera = None

# Initialize MQTT client
try:
    mqtt_client = mqtt.Client()
    mqtt_client.connect("mqtt.example.com", 1883, 60)
except Exception as e:
    print(f"Failed to initialize MQTT client: {e}")
    mqtt_client = None

# Function to handle PWM control
def control_pwm():
    while True:
        try:
            speed = input("Enter fan speed percentage (0-100) or 'q' to quit: ")
            if speed.lower() == 'q':
                break
            speed = int(speed)
            if 0 <= speed <= 100:
                fan.value = speed / 100.0
            else:
                print("Invalid input. Please enter a number between 0 and 100.")
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100.")

# Function to handle MQTT messages
def on_message(client, userdata, message):
    if message.topic == "fan/speed":
        try:
            speed = int(message.payload.decode())
            if 0 <= speed <= 100:
                fan.value = speed / 100.0
            else:
                print("Invalid MQTT message. Please enter a number between 0 and 100.")
        except ValueError:
            print("Invalid MQTT message. Please enter a number between 0 and 100.")

# Subscribe to MQTT topic
if mqtt_client:
    mqtt_client.subscribe("fan/speed")
    mqtt_client.on_message = on_message

# Start PWM control thread
pwm_thread = threading.Thread(target=control_pwm)
pwm_thread.start()

try:
    while True:
        time.sleep(1)
except KeyboardInterrupt:
    pass

# Stop PWM and release resources
if fan:
    fan.stop()
if camera:
    camera.stop()
if mqtt_client:
    mqtt_client.disconnect()

print("Program exited gracefully.")
