import serial
import time
from pymodbus.client.sync import ModbusSerialClient
from pymodbus.exceptions import ModbusIOException, ConnectionException
import signal
import sys
import logging

# Configure logging
logging.basicConfig(level=logging.WARNING, format='%(asctime)s - %(levelname)s - %(message)s')

# Define the Modbus register map
REGISTER_MAP = {
    'CONTROL': {'R/W': 'W', 'Register': 0x3100, 'functioncode': 6, 'Value': {'Stop': 0x0006, 'Start': 0x000F}},
    'STATUS': {'R/W': 'R', 'Register': 0x3000, 'functioncode': 3},
    'OPMODE': {'R/W': 'W', 'Register': 0x3500, 'functioncode': 6, 'Value': {'Position': 1}},
    'VelocityCommand': {'R/W': 'W', 'Register': 0x6F00, 'functioncode': 6},
    'VelocityFeedback': {'R/W': 'R', 'Register': 0x3B00, 'functioncode': 3, 'read_length': 2},
    'PositionCommand': {'R/W': 'W', 'Register': 0x4000, 'functioncode': 6},
    'PositionFeedback': {'R/W': 'R', 'Register': 0x3700, 'functioncode': 3, 'read_length': 2}
}

class Servo:
    def __init__(self, port='/dev/serial0', baudrate=115200):
        self.port = port
        self.baudrate = baudrate
        self.client = None
        self.serial = None
        self.setup_serial()

    def setup_serial(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=1)
            self.client = ModbusSerialClient(method='rtu', port=self.port, baudrate=self.baudrate, timeout=1)
            self.client.connect()
            logging.info("Serial connection established.")
        except (serial.SerialException, ConnectionException) as e:
            logging.error(f"Failed to establish serial connection: {e}")
            self.serial = None
            self.client = None

    def close(self):
        if self.client:
            self.client.close()
        if self.serial:
            self.serial.close()
        logging.info("Serial connection closed.")

    def read_register(self, register):
        try:
            response = self.client.read_holding_registers(register, 1, unit=1)
            if response.isError():
                raise ModbusIOException(f"Modbus read error: {response}")
            return response.registers[0]
        except (ModbusIOException, ConnectionException) as e:
            logging.error(f"Modbus read error: {e}")
            return None

    def write_register(self, register, value):
        try:
            response = self.client.write_single_register(register, value, unit=1)
            if response.isError():
                raise ModbusIOException(f"Modbus write error: {response}")
            return True
        except (ModbusIOException, ConnectionException) as e:
            logging.error(f"Modbus write error: {e}")
            return False

    def set_control(self, value):
        if value in REGISTER_MAP['CONTROL']['Value']:
            return self.write_register(REGISTER_MAP['CONTROL']['Register'], REGISTER_MAP['CONTROL']['Value'][value])
        else:
            logging.error(f"Invalid control value: {value}")
            return False

    def set_opmode(self, value):
        if value == REGISTER_MAP['OPMODE']['Value']['Position']:
            return self.write_register(REGISTER_MAP['OPMODE']['Register'], REGISTER_MAP['OPMODE']['Value']['Position'])
        else:
            logging.error(f"Invalid OPMODE value: {value}")
            return False

    def set_velocity_command(self, value):
        return self.write_register(REGISTER_MAP['VelocityCommand']['Register'], value)

    def get_velocity_feedback(self):
        try:
            response = self.client.read_holding_registers(REGISTER_MAP['VelocityFeedback']['Register'], REGISTER_MAP['VelocityFeedback']['read_length'], unit=1)
            if response.isError():
                raise ModbusIOException(f"Modbus read error: {response}")
            return response.registers[0]
        except (ModbusIOException, ConnectionException) as e:
            logging.error(f"Modbus read error: {e}")
            return None

    def set_position_command(self, value):
        return self.write_register(REGISTER_MAP['PositionCommand']['Register'], value)

    def get_position_feedback(self):
        try:
            response = self.client.read_holding_registers(REGISTER_MAP['PositionFeedback']['Register'], REGISTER_MAP['PositionFeedback']['read_length'], unit=1)
            if response.isError():
                raise ModbusIOException(f"Modbus read error: {response}")
            return response.registers[0]
        except (ModbusIOException, ConnectionException) as e:
            logging.error(f"Modbus read error: {e}")
            return None

def signal_handler(sig, frame):
    logging.warning("Signal received, cleaning up.")
    servo.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    servo = Servo()

    try:
        # Example usage
        servo.set_control('Start')
        time.sleep(1)
        servo.set_position_command(1000)
        time.sleep(1)
        print(f"Velocity Feedback: {servo.get_velocity_feedback()}")
        print(f"Position Feedback: {servo.get_position_feedback()}")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        servo.close()
```

This code defines a `Servo` class that communicates with a Modbus RTU servo motor controller over a Raspberry Pi's serial UART. It includes methods for reading and writing Modbus registers, setting control and OPMODE, and getting velocity and position feedback. The class handles errors and resource release using signal handling and logging. The program can be run in a mocked or emulated environment where the serial port is absent, logging a warning instead of crashing or exiting with a non-zero status.

