import serial
import RPi.GPIO as GPIO
import time
import logging
import paho.mqtt.client as mqtt
from gpiozero import LED
from picamera2 import Picamera2, Preview
from adafruit_circuitpython_gps import GPS

class GSMModule:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=2, power_pin=4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.power_pin = power_pin
        self.serial = None
        self.gps = None
        self.camera = None
        self.mqtt_client = None
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)
        handler = logging.StreamHandler()
        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)
        self.init_gpio()
        self.init_serial()
        self.init_gps()
        self.init_camera()
        self.init_mqtt()

    def init_gpio(self):
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.power_pin, GPIO.OUT)
        GPIO.output(self.power_pin, GPIO.HIGH)
        time.sleep(2)
        GPIO.output(self.power_pin, GPIO.LOW)

    def init_serial(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            self.logger.info(f"Serial port {self.port} opened successfully.")
        except serial.SerialException as e:
            self.logger.error(f"Failed to open serial port {self.port}: {e}")
            raise

    def init_gps(self):
        try:
            self.gps = GPS()
            self.gps.start()
            self.logger.info("GPS initialized.")
        except Exception as e:
            self.logger.error(f"Failed to initialize GPS: {e}")
            raise

    def init_camera(self):
        try:
            self.camera = Picamera2()
            self.camera.start_preview(Preview.QTGL)
            self.logger.info("Camera initialized.")
        except Exception as e:
            self.logger.error(f"Failed to initialize camera: {e}")
            raise

    def init_mqtt(self):
        try:
            self.mqtt_client = mqtt.Client()
            self.mqtt_client.on_connect = self.on_connect
            self.mqtt_client.on_message = self.on_message
            self.mqtt_client.connect("mqtt.example.com", 1883, 60)
            self.logger.info("MQTT client initialized.")
        except Exception as e:
            self.logger.error(f"Failed to initialize MQTT client: {e}")
            raise

    def on_connect(self, client, userdata, flags, rc):
        self.logger.info(f"Connected with result code {rc}")

    def on_message(self, client, userdata, msg):
        self.logger.info(f"Received message: {msg.payload.decode()} on topic {msg.topic}")

    def set_gps_reporting(self, interval_seconds=10):
        try:
            response = self.send_at_command(f"AT+GPSRD={interval_seconds}\r\n")
            if response and "OK" in response:
                self.logger.info(f"GPS reporting interval set to {interval_seconds} seconds.")
            else:
                self.logger.error("Failed to set GPS reporting interval.")
        except Exception as e:
            self.logger.error(f"Failed to set GPS reporting interval: {e}")

    def send_tcp_data(self, data, ip='192.168.100.12', port=50):
        try:
            self.send_at_command(f"AT+CIPSTART=\"TCP\",\"{ip}\",{port}\r\n")
            self.send_at_command(f"AT+CIPSEND={len(data)}\r\n")
            self.serial.write(data.encode())
            self.serial.write(b'\x1A')  # Ctrl+Z
            response = self.read_response()
            if response and "SEND OK" in response:
                self.logger.info("TCP data sent successfully.")
            else:
                self.logger.error("Failed to send TCP data.")
        except Exception as e:
            self.logger.error(f"Failed to send TCP data: {e}")

    def send_terminator(self):
        try:
            self.serial.write(b'\x1A')  # Ctrl+Z
            response = self.read_response()
            if response and "OK" in response:
                self.logger.info("Terminator sent successfully.")
            else:
                self.logger.error("Failed to send terminator.")
        except Exception as e:
            self.logger.error(f"Failed to send terminator: {e}")

    def read_response(self, attempts=5):
        try:
            for _ in range(attempts):
                response = self.serial.readline().decode().strip()
                if response:
                    self.logger.info(f"Received response: {response}")
                    return response
                time.sleep(0.1)
            self.logger.error("Timeout while reading response.")
            return None
        except Exception as e:
            self.logger.error(f"Failed to read response: {e}")
            return None

    def set_message_storage(self, storage='SM'):
        try:
            response = self.send_at_command(f"AT+CPMS=\"{storage}\",\"{storage}\",\"{storage}\"\r\n")
            if response and "OK" in response:
                self.logger.info(f"Message storage set to {storage}.")
            else:
                self.logger.error("Failed to set message storage.")
        except Exception as e:
            self.logger.error(f"Failed to set message storage: {e}")

    def send_at_command(self, command):
        try:
            self.serial.write(command.encode())
            response = self.read_response()
            if response and "OK" in response:
                self.logger.info(f"Command sent: {command}")
                return response
            else:
                self.logger.error(f"Failed to send command: {command}")
                return None
        except Exception as e:
            self.logger.error(f"Failed to send command: {command}")
            return None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

    def close(self):
        if self.serial:
            self.serial.close()
            self.logger.info("Serial port closed.")
        if self.gps:
            self.gps.stop()
            self.logger.info("GPS stopped.")
        if self.camera:
            self.camera.stop_preview()
            self.logger.info("Camera stopped.")
        if self.mqtt_client:
            self.mqtt_client.disconnect()
            self.logger.info("MQTT client disconnected.")
        GPIO.cleanup()
        self.logger.info("Resources released.")

if __name__ == "__main__":
    import signal
    import sys

    def signal_handler(sig, frame):
        print("Exiting...")
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GSMModule() as gsm:
        gsm.set_gps_reporting()
        gsm.send_tcp_data(b"Hello, world!")
        gsm.send_terminator()
        gsm.set_message_storage()

