    def signal_handler(sig, frame):
        print("Exiting...")
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with GSMModule() as gsm:
        gsm.set_gps_reporting()
        gsm.send_tcp_data(b"Hello, world!")
        gsm.send_terminator()
        gsm.set_message_storage()
