import smbus2
from contextlib import contextmanager

class I2CDevice:
    def __init__(self, address, bus_number=1):
        try:
            self.bus = smbus2.SMBus(bus_number)
            self.address = address
            self._verify_device()
        except OSError as e:
            raise RuntimeError(f"Failed to open I2C bus: {e}")
        except IOError as e:
            raise RuntimeError(f"Failed to communicate with I2C device: {e}")

    def _verify_device(self):
        try:
            self.bus.read_byte(self.address)
        except OSError as e:
            raise RuntimeError(f"Device at address {self.address} is not present or not responding: {e}")

    def write_byte(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as e:
            raise RuntimeError(f"Failed to write byte to register {register}: {e}")
        except IOError as e:
            raise RuntimeError(f"Failed to communicate with I2C device: {e}")

    def read_byte(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as e:
            raise RuntimeError(f"Failed to read byte from register {register}: {e}")
        except IOError as e:
            raise RuntimeError(f"Failed to communicate with I2C device: {e}")

    def close(self):
        try:
            self.bus.close()
        except OSError as e:
            raise RuntimeError(f"Failed to close I2C bus: {e}")

    @contextmanager
    def __enter__(self):
        yield self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

