import smbus2
from datetime import datetime, timedelta
from gpiozero import DigitalOutputDevice
from paho.mqtt import client as mqtt

class DS1338RTC:
    def __init__(self, i2c_bus=1, i2c_address=0x68, sda_pin=2, scl_pin=3):
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self.sda_pin = sda_pin
        self.scl_pin = scl_pin
        self.i2c = smbus2.SMBus(i2c_bus)
        self.sda = DigitalOutputDevice(sda_pin)
        self.scl = DigitalOutputDevice(scl_pin)
        self.check_device_presence()
        self.sda.close()
        self.scl.close()

    def check_device_presence(self):
        try:
            self.i2c.read_byte(self.i2c_address)
        except OSError as e:
            raise RuntimeError("DS1338 RTC not found at address 0x68") from e

    def read_seconds(self):
        seconds = self.i2c.read_byte_data(self.i2c_address, 0x00)
        return self.bcd_to_int(seconds)

    def write_seconds(self, seconds):
        self.i2c.write_byte_data(self.i2c_address, 0x00, self.int_to_bcd(seconds))

    def read_minutes(self):
        minutes = self.i2c.read_byte_data(self.i2c_address, 0x01)
        return self.bcd_to_int(minutes)

    def write_minutes(self, minutes):
        self.i2c.write_byte_data(self.i2c_address, 0x01, self.int_to_bcd(minutes))

    def read_hours(self):
        hours = self.i2c.read_byte_data(self.i2c_address, 0x02)
        if hours & 0x40:  # Check if 12-hour mode
            hours &= 0x3F  # Mask out the 12-hour mode bit
        return self.bcd_to_int(hours)

    def write_hours(self, hours):
        if hours > 12:
            hours -= 12
            hours |= 0x40  # Set the 12-hour mode bit
        self.i2c.write_byte_data(self.i2c_address, 0x02, self.int_to_bcd(hours))

    def read_date(self):
        date = self.i2c.read_byte_data(self.i2c_address, 0x04)
        return self.bcd_to_int(date)

    def write_date(self, date):
        self.i2c.write_byte_data(self.i2c_address, 0x04, self.int_to_bcd(date))

    def read_month(self):
        month = self.i2c.read_byte_data(self.i2c_address, 0x05)
        return self.bcd_to_int(month)

    def write_month(self, month):
        self.i2c.write_byte_data(self.i2c_address, 0x05, self.int_to_bcd(month))

    def read_year(self):
        year = self.i2c.read_byte_data(self.i2c_address, 0x06)
        return self.bcd_to_int(year)

    def write_year(self, year):
        year = year % 100  # Only store the two low BCD digits
        self.i2c.write_byte_data(self.i2c_address, 0x06, self.int_to_bcd(year))

    def bcd_to_int(self, bcd):
        return (bcd & 0xF0) >> 4 * (bcd & 0x0F)

    def int_to_bcd(self, value):
        return (value // 10 << 4) | (value % 10)

    def read_datetime(self, century=21):
        seconds = self.read_seconds()
        minutes = self.read_minutes()
        hours = self.read_hours()
        date = self.read_date()
        month = self.read_month()
        year = self.read_year()
        return datetime(century, month, date, hours, minutes, seconds)

    def write_all(self, seconds=None, minutes=None, hours=None, date=None, month=None, year=None):
        if seconds is not None:
            self.write_seconds(seconds)
        if minutes is not None:
            self.write_minutes(minutes)
        if hours is not None:
            self.write_hours(hours)
        if date is not None:
            self.write_date(date)
        if month is not None:
            self.write_month(month)
        if year is not None:
            self.write_year(year)

    def on_mqtt_connect(self, client, userdata, flags, rc):
        print("Connected to MQTT broker")

    def on_mqtt_disconnect(self, client, userdata, rc):
        print("Disconnected from MQTT broker")

    def on_mqtt_message(self, client, userdata, msg):
        print(f"Received message on {msg.topic}: {msg.payload.decode()}")

    def start_mqtt(self, broker_address, port=1883, client_id="ds1338_rtc"):
        client = mqtt.Client(client_id)
        client.on_connect = self.on_mqtt_connect
        client.on_disconnect = self.on_mqtt_disconnect
        client.on_message = self.on_mqtt_message
        client.connect(broker_address, port)
        client.loop_forever()

if __name__ == "__main__":
    try:
        rtc = DS1338RTC()
        print("RTC initialized successfully")
        # Example usage
        # rtc.write_all(hours=14, minutes=30, seconds=0)
        # print(rtc.read_datetime())
        # rtc.start_mqtt("mqtt.example.com")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Ensure the I2C bus handle is released cleanly
        if hasattr(rtc, 'i2c'):
            rtc.i2c.close()

