        minutes = self.decode_bcd(data[5])
        seconds = self.decode_bcd(data[6])
        return year, month, date, day, hours, minutes, seconds

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=datetime.utc)

    def write_all(self, year, month, date, day, hours, minutes, seconds):
        if not (2000 <= year <= 2099):
            raise ValueError("Year must be between 2000 and 2099")
        if not (1 <= month <= 12):
            raise ValueError("Month must be between 1 and 12")
        if not (1 <= date <= 31):
            raise ValueError("Date must be between 1 and 31")
        if not (0 <= day <= 6):
            raise ValueError("Day of week must be between 0 and 6")
        if not (0 <= hours <= 23):
            raise ValueError("Hours must be between 0 and 23")
        if not (0 <= minutes <= 59):
            raise ValueError("Minutes must be between 0 and 59")
        if not (0 <= seconds <= 59):
            raise ValueError("Seconds must be between 0 and 59")
        seconds &= ~0x80  # Clear CH bit
        hours &= ~0x40  # Clear 12/24-hour bit
        data = [
            self.encode_bcd(year - 2000),
            self.encode_bcd(month),
            self.encode_bcd(date),
            self.encode_bcd(day),
            self.encode_bcd(hours),
            self.encode_bcd(minutes),
            self.encode_bcd(seconds)
        ]
        try:
            self.bus.write_i2c_block_data(self.address, 0x00, data)
        except smbus2.SMBusError as e:
            raise IOError(f"Failed to write to register 0x00: {e}")

    def write_datetime(self, dt):
        self.write_all(dt.year, dt.month, dt.day, dt.weekday(), dt.hour, dt.minute, dt.second)

    def write_now(self):
        self.write_datetime(datetime.now())

    def decode_bcd(self, bcd):
        return (bcd & 0xF0) >> 4 * (bcd & 0x0F)

    def encode_bcd(self, value):
        return (value // 10 << 4) | (value % 10)

if __name__ == "__main__":
    try:
        with DS1338() as rtc:
            current_time = rtc.read_datetime()
            print(f"Current RTC time: {current_time}")
    except IOError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)
