    def __init__(self, port='/dev/ttyS0', baudrate=115200):
        self.port = port
        self.baudrate = baudrate
        self.serial = None
        self.connected = False
        self.camera = None
        self.mqtt_client = None

        # Initialize GPIO for LED
        self.led = LED(17)

        # Initialize camera
        self.camera = Picamera2()
        self.camera.configure(self.camera.create_video_configuration(main={"size": (640, 480), "format": "RGB888"}))
        self.camera.start()

        # Initialize MQTT client
        self.mqtt_client = mqtt.Client()
        self.mqtt_client.on_connect = self.on_connect
        self.mqtt_client.on_message = self.on_message

        # Set up signal handlers
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)

    def _send_command(self, command, delay=1, max_retries=3):
        if not self.serial:
            raise Exception("Serial port is not initialized")

        retries = 0
        while retries < max_retries:
            try:
                self.serial.write(command.encode('utf-8') + b'\r\n')
                time.sleep(delay)
                response = self._read_response()
                if response and ('OK' in response or 'ERROR' in response or 'FAIL' in response):
                    return response
            except serial.SerialException as e:
                print(f"Serial error: {e}")
                self.cleanup()
                raise
            except Exception as e:
                print(f"Error sending command: {e}")
                retries += 1
                time.sleep(1)

        raise Exception(f"Failed to send command '{command}' after {max_retries} retries")

    def _read_response(self):
        if not self.serial:
            raise Exception("Serial port is not initialized")

        start_time = time.time()
        response = b''
        while time.time() - start_time < 5:
            try:
                response += self.serial.read(1)
                if b'\r\n' in response:
                    return response.decode('utf-8').strip()
            except serial.SerialException as e:
                print(f"Serial error: {e}")
                self.cleanup()
                raise
            except Exception as e:
                print(f"Error reading response: {e}")
                time.sleep(0.1)

        return None

    def test_connection(self):
        response = self._send_command('AT\r\n')
        if response and 'OK' in response:
            self.connected = True
            print("Connection test passed")
        else:
            print("Connection test failed")

    def restart(self):
        response = self._send_command('AT+RST\r\n', delay=2)
        if response and 'OK' in response:
            print("Restarted successfully")
        else:
            print("Failed to restart")

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"'
        response = self._send_command(command, delay=5)
        if response and 'WIFI GOT IP' in response:
            print("Connected to WiFi")
            return True
        else:
            print("Failed to connect to WiFi")
            return False

    def on_connect(self, client, userdata, flags, rc):
        if rc == 0:
            print("Connected to MQTT broker")
        else:
            print(f"Failed to connect to MQTT broker with result code {rc}")

    def on_message(self, client, userdata, msg):
        print(f"Received message: {msg.payload.decode('utf-8')} on topic {msg.topic}")

    def cleanup(self, signum, frame):
        print("Cleaning up...")
        if self.serial:
            self.serial.close()
        if self.camera:
            self.camera.stop()
        if self.mqtt_client:
            self.mqtt_client.disconnect()
        sys.exit(0)

# Example usage
if __name__ == "__main__":
    try:
        esp = ESP8266Communicator()
        esp.test_connection()
        esp.connect_wifi('your_ssid', 'your_password')
        esp.restart()
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        esp.cleanup(None, None)

