class SimpleGPS:
    def __init__(self):
        self.serial_port = None
        self.connection = None
        self.picamera = None
        self.mqtt_client = None

    def connect(self):
        try:
            self.serial_port = serial.Serial('/dev/serial0', 9600, timeout=1)
            self.connection = True
            logging.info("Serial connection established.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port: {e}")
            return False
        except OSError as e:
            logging.error(f"Device not found: {e}")
            return False

    def read_data(self):
        if not self.connection:
            return None
        try:
            data = self.serial_port.readline().decode('utf-8', errors='ignore').strip()
            if not data:
                logging.info("No data available.")
                return None
            return data
        except serial.SerialException as e:
            logging.error(f"Serial error: {e}")
            self.close()
            return None

    def parse_gga(self, sentence):
        if sentence.startswith('$GPGGA') or sentence.startswith('$GNGGA'):
            try:
                fields = sentence.split(',')
                utc_time = fields[1]
                latitude = fields[2]
                longitude = fields[4]
                fix_quality = int(fields[6])
                num_satellites = int(fields[7])
                if latitude and longitude:
                    latitude_degrees = float(latitude[:2]) + float(latitude[2:]) / 60
                    longitude_degrees = float(longitude[:3]) + float(longitude[3:]) / 60
                    if latitude[0] == 'S':
                        latitude_degrees = -latitude_degrees
                    if longitude[0] == 'W':
                        longitude_degrees = -longitude_degrees
                    return {
                        'utc_time': utc_time,
                        'latitude': latitude_degrees,
                        'longitude': longitude_degrees,
                        'fix_quality': fix_quality,
                        'num_satellites': num_satellites
                    }
                else:
                    return None
            except (IndexError, ValueError) as e:
                logging.error(f"Malformed GGA sentence: {e}")
                return None
        else:
            return None

    def close(self):
        if self.connection:
            try:
                self.serial_port.close()
                logging.info("Serial connection closed.")
            except serial.SerialException as e:
                logging.error(f"Failed to close serial port: {e}")
            self.connection = False
        if self.picamera:
            try:
                self.picamera.stop_recording()
                self.picamera.close()
                logging.info("Camera stopped and closed.")
            except Exception as e:
                logging.error(f"Failed to close camera: {e}")
        if self.mqtt_client:
            try:
                self.mqtt_client.disconnect()
                logging.info("MQTT client disconnected.")
            except Exception as e:
                logging.error(f"Failed to disconnect MQTT client: {e}")
        self.serial_port = None
        self.picamera = None
        self.mqtt_client = None

if __name__ == "__main__":
    gps = SimpleGPS()
    if not gps.connect():
        logging.error("Failed to connect to GPS.")
        exit(1)

    try:
        while True:
            data = gps.read_data()
            if data:
                gga_data = gps.parse_gga(data)
                if gga_data:
                    logging.info(f"Parsed GGA: {gga_data}")
    except KeyboardInterrupt:
        logging.info("Keyboard interrupt detected. Closing serial connection.")
        gps.close()
    finally:
        logging.info("Exiting program.")

