from flask import Flask, request, jsonify, abort
import serial
import time
import json

app = Flask(__name__)

# In-memory data store
data_store = []

# Serial port setup
ser = None

def open_serial_port():
    global ser
    try:
        ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
    except serial.SerialException as e:
        abort(503, description=f"Failed to open serial port: {e}")

def close_serial_port():
    global ser
    if ser:
        ser.close()

@app.route('/version')
def version():
    open_serial_port()
    try:
        ser.write(b'*IDN?\n')
        time.sleep(0.1)
        response = ser.read(1024).decode('utf-8').strip()
        return response.replace('\n', '<br>')
    except Exception as e:
        return abort(503, description=f"Failed to read from serial port: {e}")
    finally:
        close_serial_port()

@app.route('/getdata')
def getdata():
    return jsonify(data_store)

@app.route('/getset/<int:item_id>')
def getset(item_id):
    for item in data_store:
        if item['id'] == item_id:
            return jsonify(item)
    abort(404)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def getpost(item_id, name):
    for item in data_store:
        if item['id'] == item_id:
            return jsonify(item)
    abort(404)

@app.route('/postjson', methods=['POST'])
def postjson():
    open_serial_port()
    try:
        if request.is_json:
            data = request.get_json()
        else:
            data = request.form.to_dict()

        if 'name' not in data:
            data['name'] = ''
        if 'done' not in data:
            data['done'] = False

        if 'id' in data:
            item_id = data['id']
        else:
            item_id = len(data_store) + 1

        data_store.append({'id': item_id, 'name': data['name'], 'done': data['done']})

        ser.write(f"SET {item_id} {data['name']} {data['done']}\n".encode('utf-8'))
        time.sleep(0.1)
        ser.write(b"GET\n")
        time.sleep(0.1)
        response = ser.read(1024).decode('utf-8').strip()
        return response.replace('\n', '<br>')
    except Exception as e:
        return abort(400, description=f"Failed to process POST request: {e}")
    finally:
        close_serial_port()

@app.route('/postjson', methods=['GET'])
def getpostjson():
    return jsonify(data_store)

if __name__ == '__main__':
    # Seed the store with two items
    data_store.append({'id': 1, 'name': 'Item 1', 'done': False})
    data_store.append({'id': 2, 'name': 'Item 2', 'done': True})

    app.run(host='0.0.0.0', port=5000)

